	set(tour_soundson, false);
	events.dispatch(stoptoursoundsevent);
	set(plugin[data].soundOn, false); 
	stop_background_sound();
);

if (device.desktop,
	if(
		%1 == none, 
			set(plugin[backgroundinterface].background,%1,0); 
		, if(
			plugin[backgroundinterface].background == %1, 
				if (
					%3 == forcesounds, 
						playsound(backgroundsound,%1,%2,0); ) 
					, 
						playsound(backgroundsound,%1,%2); 
						set(plugin[backgroundinterface].background,%1,0
					);
			);
	);
);

if(get(plugin[data].autoplay),
	if(
		%1 == none,
			set(plugin[autoguideinterface].background,%1,1,nextOnFinishSound()); 
		, if(
			plugin[autoguideinterface].background == %1,
				if (
					%3 == forcesounds, 
						playsound(autoguidesound,%1,1,nextOnFinishSound()); 
					);
			, 
				playsound(autoguidesound,%1,1,nextOnFinishSound()); 
				set(plugin[autoguideinterface].background,%1);
			) 
	)

	,


	if(
		%1 == none,
			set(plugin[autoguideinterface].background,%1,0); 
		, if(
			plugin[autoguideinterface].background == %1,
				if (
					%3 == forcesounds, 
					trace('1-2');
						playsound(autoguidesound,%1,%2); 
					);
			, 
				playsound(autoguidesound,%1,%2); 
				set(plugin[autoguideinterface].background,%1);
			) 
	);
);

 	if(layer[%1].visible == false,
		if(%1== map_exhibition,	showbackground_size();closegraphics_background(););
		if(%1== menu_exhibition, showbackground_size();closegraphics_background(););
		if(%1== menu_exhibition_en, showbackground_size();closegraphics_background(););
		if(%1== menu_share,
			if(layer[toprightbg].y == 200,
				hidebackground_size();
			);
		);

 		set(layer[%1].visible,true);
		tween(layer[%1].alpha, 1, 0.3);
	,
		tween(layer[%1].alpha, 0, 0.3,default,set(layer[%1].visible,false));
		hidebackground_size();
	);

